// ============================================
// PREPARE NOTIFICATION PAYLOAD
// ============================================
// RFC-090: Notification via Redis Streams (XADD)
// Le node Redis natif n8n ne supporte pas XADD,
// donc on utilise redis-cli via Execute Command.
// ============================================

const input = $input.first().json;

// Validate input
const action = input.body?.action || input.action || 'workflow_updated';
const workflowName = input.body?.workflow_name || input.workflow_name || input.body?.name || input.name || 'unknown';

// Valid actions
const validActions = ['workflow_added', 'workflow_modified', 'workflow_deleted', 'workflow_updated'];
if (!validActions.includes(action)) {
  throw new Error(`Invalid action: ${action}. Valid: ${validActions.join(', ')}`);
}

// Timestamp ISO
const timestamp = new Date().toISOString();

// Redis connection info (from environment or defaults)
const redisHost = $env.REDIS_HOST || 'host3.local';
const redisPort = $env.REDIS_PORT || '6379';
const redisDb = $env.REDIS_NOTIFICATIONS_DB || '5';
const streamKey = 'tools:events:stream';

// Escape special characters for shell command
const escapeShell = (str) => {
  return String(str).replace(/'/g, "'\\''");
};

return {
  // Data fields
  event: 'tools_updated',
  action: action,
  workflow_name: workflowName,
  source: 'n8n:MCP-Tools-Notify',
  timestamp: timestamp,

  // Redis connection
  redis_host: redisHost,
  redis_port: redisPort,
  redis_db: redisDb,
  stream_key: streamKey,

  // Pre-built redis-cli command
  redis_command: `redis-cli -h ${escapeShell(redisHost)} -p ${escapeShell(redisPort)} -n ${escapeShell(redisDb)} XADD ${escapeShell(streamKey)} '*' event '${escapeShell('tools_updated')}' action '${escapeShell(action)}' workflow_name '${escapeShell(workflowName)}' source '${escapeShell('n8n:MCP-Tools-Notify')}' timestamp '${escapeShell(timestamp)}'`
};

// ============================================
// PARSE XADD RESPONSE
// ============================================
// redis-cli XADD returns the stream entry ID
// Format: "1234567890123-0" (timestamp-sequence)
// ============================================

const input = $input.first().json;
const stdout = input.stdout || '';
const stderr = input.stderr || '';

// Check for errors
if (stderr && stderr.trim()) {
  throw new Error(`Redis XADD failed: ${stderr}`);
}

// Parse the stream ID from stdout
const streamId = stdout.trim();

if (!streamId || !streamId.includes('-')) {
  throw new Error(`Invalid XADD response: ${stdout}`);
}

// Get original payload from previous node
const payload = $('Prepare Payload').first().json;

return {
  success: true,
  stream_id: streamId,
  stream_key: payload.stream_key,
  event: payload.event,
  action: payload.action,
  workflow_name: payload.workflow_name,
  timestamp: payload.timestamp
};
